-- ==========================================================================
-- Park Day Companion — תוכן: חלק 1 מתוך 2
-- ==========================================================================
--
-- 145 מתקנים. להדביק ל-Supabase SQL Editor ולהריץ.
-- ⚠️ להריץ את החלקים לפי הסדר: 1, ואז 2.
--
-- נוצר על ידי scripts/build-content-seed.py מתוך src/data/experiences.json.
-- אין לערוך ביד — לעדכן את הייצוא ולהריץ את הסקריפט מחדש.
--
-- INSERT אחד מרובה-שורות. רשימת העמודות נכתבת פעם אחת.
--
-- on conflict do update מרענן את **כל** 36 העמודות מ-excluded,
-- גם כשהערך החדש NULL. עמודה שחסרה שם הייתה משאירה ערך ישן לנצח: מתקן
-- שדירוג העוצמה שלו הוסר בייצוא חדש היה נשאר עם הדירוג הישן, ושום דבר לא
-- היה נראה שבור — בתא יש ערך, הוא פשוט שגוי. לכן ה-SET נגזר מאותה רשימת
-- עמודות ולא נכתב שוב.
--
-- אפשר להריץ שוב בבטחה, כמה פעמים שרוצים.
--
-- ==========================================================================

BEGIN;

set local search_path = public, extensions;

on conflict (id) do update set
  key = excluded.key,
  park_id = excluded.park_id,
  land_id = excluded.land_id,
  kind = excluded.kind,
  type = excluded.type,
  category = excluded.category,
  status = excluded.status,
  status_note = excluded.status_note,
  admission = excluded.admission,
  reservation = excluded.reservation,
  included_with_admission = excluded.included_with_admission,
  subtype = excluded.subtype,
  name = excluded.name,
  name_i18n = excluded.name_i18n,
  aliases_i18n = excluded.aliases_i18n,
  intensity = excluded.intensity,
  opened_year = excluded.opened_year,
  duration_minutes = excluded.duration_minutes,
  height_requirement_cm = excluded.height_requirement_cm,
  gets_wet = excluded.gets_wet,
  environment = excluded.environment,
  air_conditioned = excluded.air_conditioned,
  wheelchair = excluded.wheelchair,
  motion_sickness_warning = excluded.motion_sickness_warning,
  is_motion_simulator = excluded.is_motion_simulator,
  uses_large_screens_or_3d = excluded.uses_large_screens_or_3d,
  big_drops = excluded.big_drops,
  spinning = excluded.spinning,
  skip_line_system = excluded.skip_line_system,
  sens_enclosed_dark = excluded.sens_enclosed_dark,
  sens_heights = excluded.sens_heights,
  sens_loud_sudden = excluded.sens_loud_sudden,
  sens_strobe = excluded.sens_strobe,
  max_speed_kmh = excluded.max_speed_kmh,
  inversions = excluded.inversions,
  last_verified = excluded.last_verified,
  updated_at = now();

COMMIT;
